// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function testFuzz_property(uint256 amount, uint256 reenterAmount) public {
        amount = bound(amount, 2, 100 ether);

        ReentrantReceiver r = new ReentrantReceiver(address(c));
        address actor = address(r);
        vm.deal(actor, amount);

        c.SetMinSum(0);
        c.SetLogFile(address(new LogFile()));

        vm.prank(actor);
        c.Deposit{value: amount}();

        r.arm(reenterAmount);

        uint256 beforeBal = c.balances(actor);
        vm.prank(actor);
        c.Collect(amount);
        uint256 afterBal = c.balances(actor);

        assertTrue(afterBal == beforeBal - amount);
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string Data;
        uint Val;
        uint Time;
    }

    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

contract ReentrantReceiver {
    BANK_SAFE c;
    uint256 public reenterAmount;
    bool public armed;
    bool private _entered;

    constructor(address _c) {
        c = BANK_SAFE(payable(_c));
    }

    function arm(uint256 _amount) external {
        reenterAmount = _amount;
        armed = true;
        _entered = false;
    }

    function Collect() external {
        c.Collect(reenterAmount);
    }

    fallback() external payable {
        if (armed && !_entered) {
            _entered = true;
            c.Collect(reenterAmount);
        }
    }

    receive() external payable {
        if (armed && !_entered) {
            _entered = true;
            c.Collect(reenterAmount);
        }
    }
}
